// cargamos la 1a. SCENE
	function LoadCuadricula(strcuadricula: string)
	{
		let cuadricula=parseInt(strcuadricula);

		let x=Math.floor(cuadricula / 100);
		let y=cuadricula % 100;
		
		game.currentScene().tileMap.data.setCRCmaps(fondos[x][y],mappaths[x][y],mapsfg[x][y],mapsp[x][y]);
	}
LoadCuadricula(CUADRICULA_INICIAL);

