/*	Sprite - Main Character
*/

enum MainCharacter_Estado
	{
	Normal,
	Diving,
	Climbing,
	}
	
function Behaviour_MainCharacterCanFallAndStops()
{
	// funcion cuando toca caer
	mySprite.SpriteFallDown(function(spr: Sprite)
		{
		control.EventContext.onStats(" VM : Personaje cae" );
		
		GameAPI_func_DoFall(spr);
		
		// ponemos anim de caer
		if (spr.dir == 1)	GameAPI_SPRadd_StartAnim(spr,spr.p.anims[NANIM_STANDBYDER]);
		else				GameAPI_SPRadd_StartAnim(spr,spr.p.anims[NANIM_STANDBYIZQ]);
		
		// mientras caemos el controller anulado
		ignorecontroller=1;
		});
	
	// Funcion cuando hemos tocado solido despues de CAER
	mySprite.SpriteFallDownStops(function(spr: Sprite)
		{
		GameAPI_func_StopMove(spr);
		
		// activamos controller
		ignorecontroller=0;
		});
}

function Behaviour_MainCharacterOnFastWallHitAndFall()
{
	// cuando choca con la pared si va a mucha velocidad choca y se cae
	mySprite.SpriteWallStops(function(spr: Sprite)
		{
		//control.EventContext.onStats("VM : SpriteWallStops " + spr.vx);
		
		if (spr.vx >= VEL_CHOQUE_PARED)
			{
			
			GameAPI_SPRadd_StartAnimCallbackOnEnd(spr,animArthurchocaparedycaesentadoDER,function()
				{
				GameAPI_SPRadd_StartAnim(spr,spr.p.anims[NANIM_STANDBYDER]);
				
				// activamos controller
				ignorecontroller=0;
				});
			
			// mientras esta la anim el controller anulado
			ignorecontroller=1;
			
			}
		else if (spr.vx <= -VEL_CHOQUE_PARED)
			{

			GameAPI_SPRadd_StartAnimCallbackOnEnd(spr,animArthurchocaparedycaesentadoIZQ,function()
				{
				GameAPI_SPRadd_StartAnim(spr,spr.p.anims[NANIM_STANDBYIZQ]);
				
				// activamos controller
				ignorecontroller=0;					
				});
			
			// mientras esta la anim el controller anulado
			ignorecontroller=1;
			
			}
			
		// paramos en seco
		spr.vx=0; spr.ax=0;
		
		});
}

function Behaviour_MainCharacterDive()
{
	// Desactivamos la caida ...
	mySprite.SpriteFallDown(null);	
	mySprite.SpriteFallDownStops(null);
	
	// El wall stop tampoco lo tenemos que atender, no pasamos y listos
	mySprite.SpriteWallStops(null);
}

function SpecialZones_0302(spr: Sprite)
{
	// Gestion de las especial Zone en pantallas donde puede nadar
	
	let numsp=spr.SpriteSpecialZoneNumber();
	
	if ( numsp <= -2 && numsp >= -5 )
		{
		control.EventContext.onStats(" VM : Personaje cae al agua !!!" );
		
		// hacemos la animacion DECORATION de SPLASH !!
		GameAPI_SPRadd_StartDecorationAnimCallbackOnEnd(spr,animArthurcaeagua,80,-8,-4,function()
			{
			// activamos controller y GMA (que los habia desactivado la funcion ...)
			ignorecontroller=0;
			//spr.controljs=0;						// en modo BUCEO seguimos manteniendo el controljs (elimina gravedad de caer)
			
			spr.invalidateNow();					// como la nueva animacion los costumes cambian de tamaño
			
			// pasamos el SPRITE al modo buceo
			(spr.p as GAobj_MainCharacter).ConfigMoveDiving();
			});
		
		}
	else if ( numsp >= 2 && numsp <= 5)
		{
		
		// si esta intentando subir fuera del agua ?
		if (spr.vy < 0)
			{
			//control.EventContext.onStats(" VM : Personaje intenta salir fuera del agua !!! y = " + spr.y );
			
			// si puede salir a tierra ?
			if ( numsp == 2 && spr.x == 46 && spr.dir == 2)
				{
				//control.EventContext.onStats(" VM : Personaje sube a tierra desde el agua !!! x = " + spr.x );

				// hacemos la animacion DECORATION de subir a tierra
				GameAPI_SPRadd_StartDecorationAnimCallbackOnEnd(spr,animArthursaleaguaIZQ,200,-5,-25,function()
					{
					// activamos controller y GMA (que los habia desactivado la funcion ...)
					ignorecontroller=0;
					spr.controljs=0;
					
					spr.invalidateNow();			// como la nueva animacion los costumes cambian de tamaño
					
					// pasamos el SPRITE a modo WALK Normal
					(spr.p as GAobj_MainCharacter).ConfigMoveWalkRetardAceleration();
					spr.x-=4; spr.y-=6;		// ajsutamos la posicion al cambiar de costumes
					});
				
				}
			else
				{
				
				if (spr.y < 64)
					{
					spr.invalidateNow();			// como forzamos a moverse a otro sitio desde JS
					spr.y=64;
					}
				
				}
			}
		
		}
	else if ( numsp == 6)
		{
		control.EventContext.onStats(" VM : Personaje intenta pasar por la exclusa !!! x = " + spr.x );
		
		if (spr.x > 236)
			{
			spr.invalidateNow();					// como forzamos a moverse a otro sitio desde JS
			spr.x=236;
			}
		}

}

class GAobj_MainCharacter extends GameObject
{
	protected startmoving: boolean;
	protected movestarttime: number;
	
	public estado: number;
	
	constructor()
	{
		// llama al constructor padre
        super();
		
		this.CrearAnimaciones();
		this.clones=[];
		this.kind=SpriteKind.Player;
		
		// solo tiene un CLON que es la variable global 'mySprite'
		mySprite=this.CreateClon();
		
		this.ConfigureMainCharacter();
		
		this.ConfigureController();
    }
	
	private CrearAnimaciones()
	{
		this.anims=	[
					[ animArthurdesnudowalkDER[0] ],	// 0 - 1 frame DER
					[ animArthurdesnudowalkIZQ[0] ],	// 1 - 1 frame IZQ
					[ animArthurdesnudowalkDER[0] ],	// 2 - NANIM_STANDBYDER
					[ animArthurdesnudowalkIZQ[0] ],	// 3 - NANIM_STANDBYIZQ
					animArthurdesnudowalkDER,			// 4 - NANIM_WALKDER
					animArthurdesnudowalkIZQ,			// 5 - NANIM_WALKIZQ
					[],									// 6 - NANIM_DIEDER
					[],									// 7 - NANIM_DIEIZQ		
					[],									// 8 - NANIM_STAIRSUP	
					[],									// 9 - NANIM_STAIRSDOWN	
					[],									// 10 - NANIM_FALLDER	
					[],									// 11 - NANIM_FALLIZQ	
					[],									// 12 - NANIM_JUMPDER	
					[],									// 13 - NANIM_JUMPIZQ	
					[],									// 14 - NANIM_OUCHDER	
					[],									// 15- NANIM_OUCHIZQ
					animArthurnadaDER,					// 16 - nada DER 
					animArthurnadaIZQ,					// 17 - nada IZQ
					animArthurcaeagua,					// 18 - cae agua SPLASH !!
					];	
	}
	
	private ConfigureController()
	{
		
		/*	Boton RIGHT	
		*/
		controller.right.onEvent(ControllerButtonEvent.Pressed, function ()
			{
			
			if (!ignorecontroller)
				{
				
				if ( this.estado == MainCharacter_Estado.Normal )
					{
				
					// en este tipo de movimiento , empieza algo mas tarde a desplazarse (se gestiona en gameupdate)
					this.startmoving=true; this.movestarttime=game.runtime();
					
					// el personaje empieza la anim de desplazarse pero de momento sin moverse de la posicion ...
					mySprite.dir=1;
					animation.runImageAnimation(mySprite,animArthurdesnudowalkDER,70,true);
					
					}
				else if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vx=+10;
					
					mySprite.dir=1;
					animation.runImageAnimation(mySprite,animArthurnadaDER,400,true);
					}
				
				}
			
			});
		controller.right.onEvent(ControllerButtonEvent.Released, function ()
			{
			
			if (!ignorecontroller)
				{
				
				if ( this.estado == MainCharacter_Estado.Normal )
					{
					
					// reseteamos control de delay del movimiento
					this.startmoving=false;
					
					// acabara parandose al cabo de un tiempo por la FRICCION
					mySprite.ax = 0;
					
					if (mySprite.dir == 1)	GameAPI_SPRadd_StartAnim(mySprite,mySprite.p.anims[NANIM_STANDBYDER]);
					else					GameAPI_SPRadd_StartAnim(mySprite,mySprite.p.anims[NANIM_STANDBYIZQ]);
					
					}
				else if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vx=0;
					}
				
				}
			
			});

			
		/*	Boton LEFT
		*/	
		controller.left.onEvent(ControllerButtonEvent.Pressed, function ()
			{
			
			if (!ignorecontroller)
				{
				
				if ( this.estado == MainCharacter_Estado.Normal )
					{				
				
					this.startmoving=true; this.movestarttime=game.runtime();
					
					mySprite.dir=2;
					animation.runImageAnimation(mySprite,animArthurdesnudowalkIZQ,70,true);
					
					}
				else if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vx=-10;
					
					mySprite.dir=2;
					animation.runImageAnimation(mySprite,animArthurnadaIZQ,400,true);
					}
					
				}
			
			});
		controller.left.onEvent(ControllerButtonEvent.Released, function ()
			{
			
			if (!ignorecontroller)
				{
				
				if ( this.estado == MainCharacter_Estado.Normal )
					{
					
					// reseteamos control de delay del movimiento
					this.startmoving=false;
					
					// acabara parandose al cabo de un tiempo por la FRICCION
					mySprite.ax = 0;
					
					if (mySprite.dir == 1)	GameAPI_SPRadd_StartAnim(mySprite,mySprite.p.anims[NANIM_STANDBYDER]);
					else					GameAPI_SPRadd_StartAnim(mySprite,mySprite.p.anims[NANIM_STANDBYIZQ]);
					
					}
				else if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vx=0;
					}
				
				}
			
			});
		
		
		/*	Boton UP
		*/
		controller.up.onEvent(ControllerButtonEvent.Pressed, function ()
			{
			
			if (!ignorecontroller)
				{
			
				if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vy=-10;
					}
					
				}
			
			});
		controller.up.onEvent(ControllerButtonEvent.Released, function ()
			{
			
			if (!ignorecontroller)
				{
			
				if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vy=0;
					}
					
				}
			
			});
		
		
		/*	Boton DOWN
		*/
		controller.down.onEvent(ControllerButtonEvent.Pressed, function ()
			{
			
			if (!ignorecontroller)
				{
			
				if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vy=+10;
					}
					
				}
			
			});
		controller.down.onEvent(ControllerButtonEvent.Released, function ()
			{
			
			if (!ignorecontroller)			
				{
			
				if ( this.estado == MainCharacter_Estado.Diving )
					{
					mySprite.vy=0;
					}
					
				}
			
			});
		
		
		/*	Gestion de inicio correr retardada del Personaje
		*/
		
		game.onUpdate(function()
			{
			
			if (this.startmoving == true)
				{
				if (game.runtime() - this.movestarttime >= 400)
					{
					this.startmoving=false;
					
					if ( mySprite.dir == 1)
						{
						mySprite.ax=ACELERACION_ANDAR;
						GameAPI_SPRadd_StartAnim(mySprite,animArthurdesnudowalkDER);
						}
					else
						{
						mySprite.ax=-ACELERACION_ANDAR;
						GameAPI_SPRadd_StartAnim(mySprite,animArthurdesnudowalkIZQ);
						}
					}
				}
			
			});
		
	}
	
	public ConfigMoveWalkRetardAceleration()
	{
		control.EventContext.onStats(" VM : Personaje pasa a modo WALK ACCELERATION");
		
		// configuramos un movimiento especial que empieza retardado, con aceleracion y frenada (friccion)
		mySprite.vx = 0;	mySprite.vy = 0;
		mySprite.fx = 300;	mySprite.fy = 0;
		mySprite.ax = 0;	mySprite.ay = 0;
		this.startmoving=false;
		this.movestarttime=0;
		
		// colocamos la anim de STANDBY
		if (mySprite.dir == 1)	GameAPI_SPRadd_StartAnim(mySprite,mySprite.p.anims[NANIM_STANDBYDER]);
		else					GameAPI_SPRadd_StartAnim(mySprite,mySprite.p.anims[NANIM_STANDBYIZQ]);
		
		// Comportamiento
		Behaviour_MainCharacterCanFallAndStops();
		Behaviour_MainCharacterOnFastWallHitAndFall();
		
		this.estado=MainCharacter_Estado.Normal;
	}

	public ConfigMoveDiving()
	{
		control.EventContext.onStats(" VM : Personaje pasa a modo DIVE");
	
		// configuramos el movimiento de bucear
		mySprite.vx = 0;	mySprite.vy = 0;
		mySprite.fx = 0;	mySprite.fy = 0;
		mySprite.ax = 0;	mySprite.ay = 10;
		this.startmoving=false;
		this.movestarttime=0;
		
		// colocamos la anim de bucear
		if (mySprite.dir == 1)	animation.runImageAnimation(mySprite,animArthurnadaDER,400,true);
		else					animation.runImageAnimation(mySprite,animArthurnadaIZQ,400,true);
		
		// recolocamos al personaje que viene de la anim de SPLASH!
		mySprite.x+=8;
		mySprite.y+=(4 + 24);
		
		// Comportamiento
		Behaviour_MainCharacterDive();
		
		this.estado=MainCharacter_Estado.Diving;
	}
	
	private ConfigureMainCharacter()
	{
		
		// La camara le sigue
		scene.cameraFollowSprite(mySprite);
		
		// en este GAME no hay Vx y Vy ya que usamos aceleracion y un sistema de inicio retardado
		controller.moveSprite(mySprite,0,0);
		
		// caracteristicas fisicas del movimiento
		this.ConfigMoveWalkRetardAceleration();
		
	}
	
}
let GO_mySprite=new GAobj_MainCharacter;


