/*	GAME OBJECT :: Carnivora
*/

class GAobj_Carnivora extends GameObject
{
    
	constructor()
	{
		// llama al constructor padre
        super();
		
		this.CrearAnimaciones();
		this.clones=[];
		this.kind=SpriteKind.USERK_carnivora;
		
		// Evento a INTERVALS
			// PENDIENTE hacer mejor
		game.onUpdateInterval(800, () =>
			{
			
			// recorremos todos los clones
			this.clones.forEach(function(sprc: Sprite)
				{
				
				// estamos en estado STANDBY
				if (sprc.data["sta"] == 0)
					{
					
					let separacionX=sprc.x - mySprite.x;			// positivo el personaje esta a la IZQ de la carnivora
					
					// 1er. filtro para ver si actuamos
					if ( Math.abs(separacionX) > 30 )
						{
						
						// calculamos las distancias entre ambos
						let separacionY=sprc.y - mySprite.y;
						let distancialinearectade2sprites = Math.sqrt(separacionX * separacionX + separacionY * separacionY);
						
						// 2o. filtro para ver si actuamos -> si la planta esta en escena ?
						if (distancialinearectade2sprites < 120)
							{
							
							// toca girarse para mirar al personaje, y si NO, miramos si atacamos ...
							if ( separacionX > 0 && sprc.dir != 2 )
								{
								sprc.dir=2;
								animation.runImageAnimation(sprc,sprc.p.anims[NANIM_STANDBYIZQ],1000,true);
								}
							else if ( separacionX < 0 && sprc.dir != 1 )
								{
								sprc.dir=1;
								animation.runImageAnimation(sprc,sprc.p.anims[NANIM_STANDBYDER],1000,true);
								}
							else if ( Math.percentChance(33) )		// atacamos ?
								{
								
								sprc.data["sta"]=1;					// estado ATACANDO
						
								let animacion: Image[];
								if ( sprc.dir == 1 )	animacion=sprc.p.anims[4];
								else					animacion=sprc.p.anims[5];
								
								// cuando acaba la animacion , hacemos su callback
								animation.runImageAnimation(sprc,animacion,DEFAULT_MSEG_FRAMES_ANIM,false,function()
									{
									// cuando ya ha abierto la boca disparamos y cerramos la boca
									
									// disparamos projectile
									let projectile = sprites.createProjectileFromSprite(img`
																						. . 6 6 6 6 . . 
																						. 6 d 4 4 4 6 . 
																						6 1 b 1 1 4 d 6 
																						c 1 b b 4 4 1 c 
																						. c b b b d c . 
																						. . c c c c . . 
																						`,sprc,
																						-(separacionX / distancialinearectade2sprites) * 100,
																						-(separacionY / distancialinearectade2sprites) * 100,);
									projectile.setFlag(SpriteFlag.AutoDestroy,true);	// esta creo que ya la pone por defecto Arcade Makecode
									projectile.setFlag(SpriteFlag.Ghost,true);
									
									// hacemos la animacion que cierre la boca
									let animacion: Image[];
									if ( sprc.dir == 1 )	animacion=sprc.p.anims[6];
									else					animacion=sprc.p.anims[7];
									animation.runImageAnimation(sprc,animacion,DEFAULT_MSEG_FRAMES_ANIM,false,function()
										{
										sprc.dir=0;				// forzamos a que se recalcule la anim de STANDBY
										sprc.data["sta"]=0;		// estado STANDBY
										});
										
									});
								
								}
								
							}
						
						}
						
					}
				});
			
			});
		
    }
	
	private CrearAnimaciones()
	{
		this.anims=	[
					[ animPlantaCarnivoraStandbyDER[1] ],			// 0 - 1 frame DER
					[ animPlantaCarnivoraStandbyIZQ[1] ],			// 1 - 1 frame IZQ
					animPlantaCarnivoraStandbyDER,					// 2 - NANIM_STANDBYDER
					animPlantaCarnivoraStandbyIZQ,					// 3 - NANIM_STANDBYIZQ
					animPlantaCarnivoraDisparoPart1DER,				// 4 -
					animPlantaCarnivoraDisparoPart1IZQ,				// 5 -
					animPlantaCarnivoraDisparoPart2DER,				// 6 -
					animPlantaCarnivoraDisparoPart2IZQ,				// 7 -
					];	
	}
	
	public CreateClonAt(x: number, y: number): Sprite
	{	
		let spr: Sprite;
		
		spr=sprites.create(this.anims[0][0],this.kind);
			spr.p=this;										// apunta al objeto PADRE
			this.clones.push(spr);
			
		// por defecto ya empieza a 0 !!!
		//spr.vx = spr.vy = 0;
		
		spr.setPosition(x,y);
		
		// configuracion del movimiento inicial
		spr.dir=1;
		animation.runImageAnimation(spr,spr.p.anims[NANIM_STANDBYDER],1000,true);

		// Estado de la Planta carnivora
		spr.data["sta"]=0;
		
		return spr;
    }
	
}
let GO_carnivora=new GAobj_Carnivora;


